/*
 * pet.r - resources for Pip
 *
 * The 'SIZE' resource marks the app as a good background citizen so it keeps
 * getting time (and keeps animating) while you work in another app. Flags word
 * 0x5C80 sets: acceptSuspendResumeEvents (0x4000), canBackground (0x1000),
 * doesActivateOnFGSwitch (0x0800), backgroundAndForeground (0x0400),
 * is32BitCompatible (0x0080). Then preferred (100K) and minimum (80K) sizes.
 * Written as raw data so it needs no Rez template includes.
 */

data 'SIZE' (-1) {
    $"5C80"          /* flags                         */
    $"00019000"      /* preferred memory size = 102400 */
    $"00014000"      /* minimum memory size   =  81920 */
};

